    77	    this.maxEntryBytes = options.maxEntryBytes ?? HISTORY_CACHE_MAX_ENTRY_BYTES;
    78	    this.maxTotalBytes = options.maxTotalBytes ?? HISTORY_CACHE_MAX_TOTAL_BYTES;
