    14	export async function authenticateSessionHistoryCacheUser(
    15	  fetcher: Fetcher = fetch,
    16	): Promise<string | null> {
    17	  try {
    18	    const response = await fetcher("/auth/me", {
    19	      cache: "no-store",
    20	      credentials: "include",
    21	      headers: { Accept: "application/json" },
    22	    });
    23	    if (!response.ok) return null;
    24	    const body: unknown = await response.json();
    25	    if (
    26	      !isRecord(body) ||
    27	      body.authenticated !== true ||
    28	      !isCanonicalHistoryCacheUserId(body.user_id)
    29	    ) {
    30	      return null;
    31	    }
    32	    return body.user_id;
    33	  } catch {
    34	    return null;
    35	  }
    36	}
