    38	export async function bindHistoryCachePort(
    39	  port: MessagePort,
    40	  store: HistoryCacheStore,
    41	  authenticate: Authenticate = authenticateSessionHistoryCacheUser,
    42	): Promise<void> {
    43	  let authenticatedUserId: string | null = null;
    44	  try {
    45	    authenticatedUserId = await authenticate();
    46	  } catch {
    47	    authenticatedUserId = null;
    48	  }
    49	  if (!isCanonicalHistoryCacheUserId(authenticatedUserId)) {
    50	    port.close();
    51	    return;
    52	  }
    53	  port.onmessage = (message) => {
    54	    if (
    55	      !isRecord(message.data) ||
    56	      message.data.userId !== authenticatedUserId
    57	    ) {
    58	      return;
    59	    }
    60	    const response = processHistoryCacheRequest(store, message.data);
    61	    if (response !== null) port.postMessage(response);
    62	  };
    63	  port.start();
    64	}

