820	    const cacheUserId = options.cacheUserId;
821	    const cacheClient =
822	      typeof cacheUserId === "string" &&
823	      cacheUserId.length >= 1 &&
824	      cacheUserId.length <= 256
825	        ? getSessionHistoryCacheClient()
826	        : null;
827	    let liveSucceeded = false;
828	    const livePromise = loadLiveBundledSessionHistory(
829	      transport,
830	      sessionId,
831	      options,
832	    );
833	    void livePromise.then(
834	      () => {
835	        liveSucceeded = true;
836	      },
837	      () => undefined,
838	    );
839	    const cachedPromise =
840	      cacheClient && !options.skipCacheRead
841	        ? cacheClient
842	            .get(cacheUserId as string, sessionId)
843	            .then(async (rawEnvelopes) => {
844	              if (rawEnvelopes === null || liveSucceeded) return;
845	              try {
846	                const cached = await loadCachedBundledSessionHistory(
847	                  rawEnvelopes,
848	                  sessionId,
849	                  options,
850	                );
851	                if (!liveSucceeded) {
852	                  options.onCachedHistory?.(
853	                    cached.messages,
854	                    cached.activeRunId,
855	                  );
856	                }
857	              } catch {
858	                if (!options.isCancelled?.()) {
859	                  await cacheClient.delete(cacheUserId as string, sessionId);
860	                }
861	              }
862	            })
863	            .catch(() => undefined)
864	        : Promise.resolve();
