 34	export class SessionHistoryCacheClient {
 35	  private worker: WorkerLike | null = null;
 36	  private port: MessagePort | null = null;
 37	  private unavailable = false;
 38	  private disposed = false;
 39	  private counter = 0;
 40	  private readonly pending = new Map<string, PendingRequest>();
