 44	  private ensurePort(): MessagePort | null {
 45	    if (this.disposed || this.unavailable) return null;
 46	    if (this.port) return this.port;
 47	    try {
 48	      const worker = this.workerFactory();
 49	      const port = worker.port;
 50	      this.worker = worker;
 51	      this.port = port;
 52	      worker.onerror = (event) => {
 53	        event.preventDefault();
 54	        this.markUnavailable();
 55	      };
 56	      port.onmessage = (event) => this.receive(event.data);
