 59	      return port;
 60	    } catch {
 61	      this.markUnavailable();
 62	      return null;
 63	    }
 64	  }
 65	
 66	  private markUnavailable(): void {
 67	    this.unavailable = true;
 68	    this.failAll();
 69	    if (this.worker) this.worker.onerror = null;
 70	    if (this.port) {
 71	      this.port.onmessage = null;
 72	      this.port.onmessageerror = null;
 73	      this.port.close();
 74	    }
 75	    this.worker = null;
 76	    this.port = null;
 77	  }
 78	
 79	  private failAll(): void {
 80	    for (const [requestId, request] of this.pending) {
 81	      clearTimeout(request.timeout);
 82	      this.pending.delete(requestId);
 83	      request.resolve(null);
 84	    }
