126	  private request(
127	    operation: Operation,
128	    userId: string,
129	    sessionId: string,
130	    envelopes?: unknown[],
131	  ): Promise<unknown[] | null> {
132	    const port = this.ensurePort();
133	    if (!port || this.pending.size >= MAX_PENDING_REQUESTS)
134	      return Promise.resolve(null);
